def oracle(input):
    n = input[0]
    offers = input[1]
    by_end = [[] for _ in range(n)]
    for s, e, g in offers:
        by_end[e].append((s, g))
    dp = [0] * n
    for i in range(n):
        best = dp[i - 1] if i > 0 else 0
        for s, g in by_end[i]:
            cand = g + (dp[s - 1] if s > 0 else 0)
            if cand > best:
                best = cand
        dp[i] = best
    return dp[n - 1] if n > 0 else 0

